<script setup lang="ts">import {ShieldCheck,LockKeyhole} from 'lucide-vue-next'
const oldPassword=ref('');const newPassword=ref('');const confirmPassword=ref('');const busy=ref(false);const message=ref('')
async function change(){message.value='';if(newPassword.value!==confirmPassword.value){message.value='Mật khẩu xác nhận không trùng khớp';return}busy.value=true;try{await $fetch('/api/profile/password',{method:'POST',body:{oldPassword:oldPassword.value,newPassword:newPassword.value}});message.value='Đã đổi mật khẩu. Vui lòng ghi nhớ mật khẩu mới.';oldPassword.value='';newPassword.value='';confirmPassword.value=''}catch(e){message.value=readableError(e)}finally{busy.value=false}}
</script>
<template><div class="space-y-4"><div><h2 class="text-xl font-black">Bảo mật tài khoản</h2><p class="text-sm text-muted">Đổi mật khẩu đăng nhập tài khoản mô phỏng.</p></div><form class="panel max-w-2xl space-y-4 p-5" @submit.prevent="change"><h3 class="section-label"><LockKeyhole class="text-brand-700" :size="21"/>Đổi mật khẩu</h3><div><label class="field-label">Mật khẩu hiện tại</label><input v-model="oldPassword" type="password" class="field" required autocomplete="current-password"/></div><div><label class="field-label">Mật khẩu mới (ít nhất 10 ký tự)</label><input v-model="newPassword" type="password" class="field" required minlength="10" autocomplete="new-password"/></div><div><label class="field-label">Nhập lại mật khẩu mới</label><input v-model="confirmPassword" type="password" class="field" required minlength="10" autocomplete="new-password"/></div><p v-if="message" class="rounded-lg bg-brand-50 p-3 text-sm text-brand-800">{{message}}</p><button class="btn-primary" :disabled="busy||!oldPassword||newPassword.length<10" type="submit"><ShieldCheck :size="16"/>{{busy?'Đang cập nhật...':'Cập nhật mật khẩu'}}</button></form><p class="max-w-2xl rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs leading-relaxed text-amber-800">Đây là đăng nhập mẫu có mật khẩu hash và phiên cookie được ký. SSO Keycloak, MFA và OIDC sẽ được tích hợp tại tầng lõi trước khi vận hành thật.</p></div></template>
